use vstd::prelude::*;

verus! {

fn reverse(a: &[i32]) -> (result: Vec<i32>)
    ensures
        // The result has the same length as the input slice
        result.len() == a.len(),
        // For each position i in result, result[i] = a[a.len() - 1 - i]
        forall |i: int|
            0 <= i && i < result.len() as int ==>
                result[i as usize] == a[(a.len() - 1 - (i as usize))],
{
    let n = a.len();
    // Pre‐allocate a vector of capacity n
    let mut result: Vec<i32> = Vec::with_capacity(n);
    let mut i: usize = 0;

    // Build up result by pushing a[n-1], a[n-2], ..., a[0]
    while i < n
        invariant
            // loop index stays in [0, n]
            i <= n,
            // the vector's current length equals i
            result.len() == i,
            // the prefix of length i of result is already the reverse of
            // the suffix of length i of a
            forall |j: int|
                0 <= j && j < i as int ==>
                    result[j as usize] == a[n - 1 - (j as usize)],
        decreases n - i,
    {
        let old_i = i;
        // pick the element from the end of a
        let v = a[n - 1 - i];
        // append it
        result.push(v);
        // now result.len() == old_i + 1
        assert(result.len() == old_i + 1);
        // and the newly pushed element is in the correct place
        assert(result[old_i] == a[n - 1 - old_i]);
        // advance
        i = i + 1;
    }

    result
}

} // verus!

